const $=s=>document.querySelector(s);
const links=[['home','◫','Overview'],['business','◇','Business Intelligence'],['content','▦','Content Hub'],['articles','▤','Articles'],['keywords','⌕','Keywords'],['audit','◎','SEO Audit'],['local','⌖','Local SEO'],['social','◈','Social Media'],['analytics','↗','Analytics'],['integrations','⊞','Integrations'],['preferences','⚙','Preferences']];
const seed=[{id:1,title:'How to build an SEO content strategy that lasts',keyword:'SEO content strategy',status:'In review',score:94,date:'Sep 12',channel:'Article'},{id:2,title:'A practical guide to brand voice consistency',keyword:'brand voice guidelines',status:'Scheduled',score:91,date:'Sep 14',channel:'Article'},{id:3,title:'Local SEO checklist for growing businesses',keyword:'local SEO checklist',status:'Draft',score:82,date:'Sep 16',channel:'Article'},{id:4,title:'5 ways to turn one article into a week of content',keyword:'content repurposing',status:'Published',score:96,date:'Sep 10',channel:'LinkedIn'}];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let articles=read('brand-poc-articles',seed), voice=read('brand-poc-voice',{tone:'Professional & warm',formality:'Balanced',terms:'consultation, practical guidance, your business',banned:'guaranteed, #1, instant results',cta:'Book a consultation',sample:'We help your business turn useful ideas into content your audience can trust.',intensity:65}),filter='All',period='30';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Browser storage is unavailable. Changes last for this session.');return false}}
function toast(msg){if(read('brand-poc-prefs',{notifications:true}).notifications===false && !msg.includes('Preferences'))return;$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function badge(status){return `<span class="pill ${status==='In review'?'amber':status==='Draft'?'blue':''}">${esc(status)}</span>`}
function heading(title,sub,action=''){return `<div class="pagehead"><div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
const createBtn='<button class="btn primary" data-action="create">＋ Create content</button>';
function stats(){const n=period==='7'?['6,284','84','36','4']:['24,892','128','146','18'];return `<div class="stats">${['Organic sessions','Keywords in top 10','Conversions','Content published'].map((s,i)=>`<div class="card"><div class="statlabel">${s}<span>${['↗','⌕','◎','▤'][i]}</span></div><div class="statnumber">${n[i]}</div><div class="delta">↗ ${['18.6','12.3','24.8','28.6'][i]}% <span>vs. previous period</span></div></div>`).join('')}</div>`}
function chart(){return `<div class="card"><div class="cardhead"><div><h2>Organic growth</h2><small>Your content is finding its audience</small></div><select aria-label="Reporting period" id="period" style="width:auto;margin:0;padding:7px;font-size:12px"><option value="30" ${period==='30'?'selected':''}>Last 30 days</option><option value="7" ${period==='7'?'selected':''}>Last 7 days</option></select></div><div class="legend"><span><i class="dot"></i>Organic sessions</span><span><i class="dot gray"></i>Previous period</span></div><svg class="chart" viewBox="0 0 620 200" preserveAspectRatio="none" role="img" aria-label="Illustrative organic traffic trending upward"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#bdd5a6" stop-opacity=".4"/><stop offset="1" stop-color="#bdd5a6" stop-opacity="0"/></linearGradient></defs>${[30,75,120,165].map((y,i)=>`<line x1="34" y1="${y}" x2="620" y2="${y}"/><text x="0" y="${y+3}">${period==='7'?['900','600','300','0'][i]:['1.5k','1k','500','0'][i]}</text>`).join('')}<path d="M35 152L75 134L115 145L155 111L195 125L235 99L275 102L315 76L355 87L395 65L435 79L475 40L515 55L555 29L615 18V180H35Z" fill="url(#area)"/><path d="M35 160L75 150L115 158L155 139L195 145L235 130L275 142L315 119L355 125L395 111L435 117L475 97L515 108L555 84L615 89" fill="none" stroke="#ccd5c4" stroke-width="2" stroke-dasharray="5 5"/><path d="M35 152L75 134L115 145L155 111L195 125L235 99L275 102L315 76L355 87L395 65L435 79L475 40L515 55L555 29L615 18" fill="none" stroke="#458164" stroke-width="2.7"/></svg><div class="chartfoot">${(period==='7'?['Sep 5','Sep 6','Sep 7','Sep 8','Sep 9','Sep 10','Sep 11']:['Aug 13','Aug 18','Aug 23','Aug 28','Sep 2','Sep 7','Sep 11']).map(d=>`<span>${d}</span>`).join('')}</div><small style="margin-top:15px">Illustrative data · Search Console + Analytics · Sep 11, 2026</small></div>`}
const scoreItems=[['Technical health',88,20],['Content & intent',92,25],['On-page SEO',84,15],['Internal linking',72,10],['Schema',80,10],['Authority & sources',86,10],['Conversion & CTA',90,10]];
function health(){return `<div class="card"><div class="cardhead"><h2>SEO health</h2><span class="pill">Looking good</span></div><div class="scorewrap"><div class="score"><div>86<small>OUT OF 100</small></div></div><div><h3>A strong foundation</h3><p class="sectionnote" style="margin-top:7px">3 opportunities to improve<br>your search visibility.</p></div></div>${scoreItems.slice(0,3).map(([n,v])=>`<div class="barrow"><span class="muted">${n}</span><b>${v}<span class="muted">/100</span></b></div><div class="track"><i style="width:${v}%"></i></div>`).join('')}<a href="#audit" class="textbtn" style="display:block;margin-top:20px;text-decoration:none">View full audit <span style="float:right">↗</span></a></div>`}
function table(items=articles){return `<div class="tablewrap"><table><thead><tr><th>CONTENT / PRIMARY KEYWORD</th><th>STATUS</th><th>SEO SCORE</th><th>PUBLISH DATE</th><th></th></tr></thead><tbody>${items.length?items.map(a=>`<tr><td>${esc(a.title)}<small>${esc(a.keyword)} · ${esc(a.channel)}</small></td><td>${badge(a.status)}</td><td><span style="color:#60864b">${a.score||'—'}</span>${a.score?' <span class="muted">/100</span>':''}</td><td class="muted">${esc(a.date)}</td><td><button class="textbtn" data-review="${a.id}">Open ↗</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No content in this stage yet.</td></tr>'}</tbody></table></div>`}
function home(){return heading('A little more growth, every day.','Here’s what’s happening with your brand today.',createBtn)+`<div class="banner"><div class="flex"><span class="bannericon">✧</span><div><h3>Your brand is ready. Let’s put it to work.</h3><p>Business profile verified · Brand voice approved · Your next step: review your content plan.</p></div></div><button class="btn" data-go="content">View content plan →</button></div>`+stats()+`<div class="grid">${chart()}${health()}</div><div class="grid"><div class="card tablecard"><div class="cardhead"><div><h2>Your content pipeline</h2><small>From a good idea to your next published story</small></div><button class="textbtn" data-go="content">View all →</button></div>${table(articles.slice(0,4))}</div><div class="card"><div class="cardhead"><h2>Recommended next steps</h2><span>✧</span></div><div class="task"><span class="tasknum">01</span><div><h3>Give your content the green light</h3><p>${articles.filter(a=>a.status==='In review').length} article ready for your review. Check the voice, facts, and SEO before approving.</p><button class="textbtn" data-action="reviewnext">Review content →</button></div></div><div class="task"><span class="tasknum">02</span><div><h3>Connect your content</h3><p>3 pages could benefit from relevant internal links.</p><button class="textbtn" data-go="audit">Explore opportunities →</button></div></div><div class="task"><span class="tasknum">03</span><div><h3>Make every word sound like you</h3><p>Fine-tune tone, terminology, and calls to action in your brand voice.</p><button class="textbtn" data-go="business">View brand voice →</button></div></div></div></div><div class="grid"><div class="card"><div class="cardhead"><h2>Automation activity</h2><span class="pill">Approval required</span></div><div class="task"><span class="tasknum">✓</span><div><h3>Brand voice check completed</h3><small>Content strategy article · 96% match · 24 minutes ago</small></div></div><div class="task"><span class="tasknum">✓</span><div><h3>Weekly keyword research completed</h3><small>12 opportunities identified · 1 hour ago</small></div></div></div><div class="card"><div class="cardhead"><h2>Coming up next</h2><span class="muted">SEPTEMBER</span></div><div class="task"><span class="tasknum">14</span><div><h3>Brand voice consistency</h3><small>Article · 10:00 AM IST</small></div></div><div class="task"><span class="tasknum">16</span><div><h3>Local SEO checklist</h3><small>Draft · Awaiting review</small></div></div></div></div>`}
function content(){return heading('Your ideas, moving forward.','Plan, review, and manage your brand’s content.',createBtn)+`<div class="stats">${['Draft','In review','Scheduled','Published'].map(s=>`<div class="card"><div class="statlabel">${s}</div><div class="statnumber">${articles.filter(a=>a.status===s).length}</div><small>In this demo workspace</small></div>`).join('')}</div><div class="tabs">${['All','Draft','In review','Approved','Scheduled','Published'].map(s=>`<button class="btn ${filter===s?'active':''}" data-filter="${s}">${s}</button>`).join('')}</div><div class="card tablecard"><div class="cardhead"><h2>Content library</h2><span class="muted">${articles.length} pieces</span></div>${table(articles.filter(a=>filter==='All'||a.status===filter))}</div>`}
function business(){return heading('The knowledge behind your brand.','Verified business context and a voice that sounds like you.')+`<div class="grid"><div class="card"><div class="cardhead"><h2>Business knowledge profile</h2><span class="pill">Demo profile</span></div>${[['Business','Our Brand','Example profile'],['Industry','Marketing & content strategy','Business overview'],['Audience','Growing businesses and marketing teams','Audience brief'],['Services','SEO strategy, content planning, brand voice','Service catalog'],['Primary CTA',voice.cta,'Approved voice rules']].map(([k,v,s])=>`<div class="task"><div><small>${k}</small><h3 style="margin-top:7px">${esc(v)}</h3><small>Evidence: ${s} · Sample source</small></div></div>`).join('')}</div><div class="card"><h2>How your voice is applied</h2><div class="task"><span class="tasknum">1</span><div><h3>Verified business facts</h3><p>Company, audience, and service context.</p></div></div><div class="task"><span class="tasknum">2</span><div><h3>Relevant source evidence</h3><p>Approved knowledge selected for the topic.</p></div></div><div class="task"><span class="tasknum">3</span><div><h3>Your brand voice</h3><p>Style rules applied without changing the facts.</p></div></div><div class="banner" style="margin:20px 0 0;padding:15px"><p>Voice rules are stored as preferences. This POC does not train or call an AI model.</p></div></div></div><form id="voiceform" class="card"><div class="cardhead"><div><h2>Brand voice studio</h2><small>Saved locally in this browser</small></div><button class="btn primary">Save brand voice</button></div><div class="formgrid"><label>Overall tone<select name="tone">${['Professional & warm','Clear & confident','Friendly & conversational','Expert & technical'].map(s=>`<option ${voice.tone===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Formality<select name="formality">${['Casual','Balanced','Formal'].map(s=>`<option ${voice.formality===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Preferred terms<input name="terms" value="${esc(voice.terms)}"></label><label>Words and claims to avoid<input name="banned" value="${esc(voice.banned)}"></label><label>Preferred call to action<input required name="cta" value="${esc(voice.cta)}"></label><label>Voice intensity<input type="range" name="intensity" min="0" max="100" value="${voice.intensity}"><small>Subtle ↔ Expressive</small></label><label class="full">Approved writing sample<textarea name="sample">${esc(voice.sample)}</textarea></label></div></form>`}
const keywords=[['SEO content strategy','Informational','2,400','32','High'],['brand voice guidelines','Informational','1,900','28','High'],['content automation platform','Commercial','1,600','46','Medium'],['local SEO checklist','Informational','3,600','38','High'],['content repurposing','Informational','4,400','51','Medium'],['SEO content services','Commercial','880','27','High']];
function keywordPage(){return heading('Find your next opportunity.','Sample keyword research, grouped by intent and business relevance.')+`<div class="card"><div class="cardhead"><h2>Keyword opportunities</h2><input id="keywordsearch" placeholder="Search keywords…" aria-label="Search keywords" style="width:230px;margin:0"></div><div id="keywordtable">${keywordTable('')}</div></div>`}
function keywordTable(q){return `<div class="tablewrap"><table><thead><tr><th>KEYWORD</th><th>INTENT</th><th>MONTHLY VOLUME</th><th>DIFFICULTY</th><th>PRIORITY</th><th></th></tr></thead><tbody>${keywords.filter(r=>r[0].includes(q.toLowerCase())).map(r=>`<tr>${r.map((v,i)=>`<td>${i===4?badge(v):esc(v)}</td>`).join('')}<td><button class="textbtn" data-keyword="${r[0]}">Create brief →</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No keywords match your search.</td></tr>'}</tbody></table></div>`}
function audit(){return heading('A clearer path to better SEO.','An explainable score, with practical actions to improve it.')+`<div class="grid">${health()}<div class="card"><div class="cardhead"><h2>How the score is calculated</h2><span class="pill">Weighted score: 86</span></div>${scoreItems.map(([n,v,w])=>`<div class="barrow"><span>${n} <span class="muted">· ${w}% weight</span></span><b>${v}</b></div><div class="track"><i style="width:${v}%"></i></div>`).join('')}<small>Weighted result 85.8, rounded to 86. All checks are illustrative.</small></div></div><div class="card"><h2>Prioritized improvements</h2>${[['Add internal links to three service pages','Connect relevant articles to service pages so readers can find the next useful step.','High impact'],['Complete organization schema','Review name, URL, and contact fields before adding structured data.','Medium impact'],['Improve two meta descriptions','Write unique summaries that reflect the page’s intent and value.','Medium impact']].map(([t,d,p])=>`<div class="task"><span class="tasknum">↗</span><div><h3>${t}</h3><p>${d}</p>${badge(p)}</div></div>`).join('')}</div>`}
function integrations(){return heading('Connect the tools you work with.','Integration previews for your future production workspace.')+`<div class="formgrid">${[['WordPress','Publish approved articles to your website.'],['Google Search Console','Track clicks, impressions, and indexing.'],['Google Analytics','Measure sessions and conversions.'],['Google Business Profile','Manage local posts and business visibility.'],['LinkedIn','Schedule professional, brand-aware content.'],['Instagram','Adapt your ideas into visual-first stories.']].map(([n,d])=>`<div class="card"><div class="cardhead"><h2>${n}</h2><span class="pill blue">Not connected</span></div><p class="sectionnote">${d}</p><button class="btn" style="margin-top:20px" data-connect="${n}">View connection details ↗</button></div>`).join('')}</div>`}
function preferences(){const p=read('brand-poc-prefs',{approval:true,notifications:true});return heading('Your workspace, your rules.','Control how content moves through your workflow.')+`<form id="prefsform" class="card"><h2>Automation preferences</h2><div class="switchrow"><div><h3>Require content approval</h3><small>Every draft must be reviewed before scheduling.</small></div><input type="checkbox" checked disabled aria-label="Require approval"></div><div class="switchrow"><div><h3>Show completion notifications</h3><small>Show an in-app message when a demo action finishes.</small></div><input type="checkbox" name="notifications" ${p.notifications?'checked':''} aria-label="Show completion notifications"></div><div class="formgrid" style="margin-top:22px"><label>Language<select><option>English (India)</option></select></label><label>Workspace timezone<select><option>Asia/Kolkata · UTC+05:30</option></select></label></div><button class="btn primary">Save preferences</button><p class="sectionnote" style="margin-top:15px">Publishing remains simulated in this proof of concept. Human review is always required.</p></form>`}
function localPage(){return heading('Make your brand easier to find nearby.','A preview of local visibility and review management.')+`<div class="stats">${[['Locations','1'],['Profile completeness','92%'],['Average rating','4.8'],['Reviews awaiting reply','2']].map(([n,v])=>`<div class="card"><div class="statlabel">${n}</div><div class="statnumber">${v}</div><small>Illustrative local data</small></div>`).join('')}</div><div class="grid"><div class="card"><h2>Customer reviews</h2>${[['Alex M.','Helpful team and clear guidance throughout the process.'],['Taylor R.','Great experience. I would have liked more frequent updates.']].map(([n,t])=>`<div class="task"><div><h3>${n} <span style="color:#ae9540">★★★★★</span></h3><p>${t}</p><button class="textbtn" data-reply="${n}">Preview reply →</button></div></div>`).join('')}</div><div class="card"><h2>Location profile</h2><p class="sectionnote" style="margin-top:20px">Our Brand · Hyderabad<br>Sample location profile<br>Address and hours awaiting verification</p><button class="btn" style="margin-top:22px" data-go="integrations">Set up Google Business Profile</button></div></div>`}
function social(){return heading('One idea. A voice for every channel.','Preview how an article becomes platform-specific content.')+`<div class="card"><div class="cardhead"><h2>Repurpose your content</h2><span class="pill">Sample preview</span></div><label>Source article<select id="socialsource">${articles.map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('')}</select></label><div class="tabs">${['LinkedIn','Instagram','Facebook','X'].map(n=>`<button class="btn" data-social="${n}">${n}</button>`).join('')}</div><div id="socialpreview" class="banner" style="display:block"><h3>Choose a channel</h3><p>See how the structure, tone, and call to action adapt to the platform.</p></div></div>`}
function render(){const page=location.hash.slice(1)||'home';const item=links.find(l=>l[0]===page)||links[0];$('#nav').innerHTML=links.map(([id,icon,label])=>`<a href="#${id}" class="${id===item[0]?'active':''}" ${id===item[0]?'aria-current="page"':''}><span class="icon">${icon}</span>${label}</a>`).join('');$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${item[2]}`;$('#main').innerHTML=({home,content,articles:content,business,keywords:keywordPage,audit,analytics:()=>heading('See the impact of your content.','Illustrative performance across search and content.')+stats()+`<div class="grid">${chart()}${health()}</div>`,integrations,preferences,local:localPage,social}[page]||home)()}
function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal()}
function create(keyword=''){modal(`<div class="cardhead"><h2>Create a content brief</h2><button class="textbtn" data-close>Close ✕</button></div><p>Start with a topic. A sample brief will be added to your content pipeline for review.</p><form id="createform"><label>Article title<input required name="title" maxlength="160" placeholder="e.g. A practical guide to content strategy" value="${esc(keyword?`A practical guide to ${keyword}`:'')}"></label><label>Primary keyword<input required name="keyword" maxlength="100" placeholder="e.g. SEO content strategy" value="${esc(keyword)}"></label><label>Search intent<select name="intent"><option>Informational</option><option>Commercial</option><option>Local</option></select></label><button class="btn primary">Create sample brief</button></form>`)}
function review(id){const a=articles.find(x=>x.id===id);if(!a)return;modal(`<div class="cardhead"><span>${badge(a.status)}</span><button class="textbtn" data-close>Close ✕</button></div><h2>${esc(a.title)}</h2><small>Primary keyword: ${esc(a.keyword)} · ${a.score?'SEO score '+a.score:'Not yet scored'}</small><p><b>Sample content brief</b><br>Help growing businesses understand ${esc(a.keyword)} through practical steps, useful examples, and a clear next action.</p><h3>Suggested outline</h3><p>1. What ${esc(a.keyword)} means for your business<br>2. Build a practical approach<br>3. Common mistakes to avoid<br>4. Measure progress and choose your next step</p><h3>Brand and quality checks</h3><p>Tone: ${esc(voice.tone)} · ${esc(voice.formality)}<br>CTA: ${esc(voice.cta)}<br>Avoid: ${esc(voice.banned)}<br>Evidence: sample business profile. Claims need human verification.</p><p class="sectionnote">This is a template preview. Scores and quality checks are sample data, not live AI evaluations.</p><div class="actions">${a.status==='Draft'?`<button class="btn primary" data-status="In review" data-id="${a.id}">Send for review</button>`:a.status==='In review'?`<button class="btn primary" data-status="Approved" data-id="${a.id}">Approve content</button><button class="btn" data-status="Draft" data-id="${a.id}">Request revision</button>`:a.status==='Approved'?`<button class="btn primary" data-schedule="${a.id}">Schedule demo</button>`:a.status==='Scheduled'?'<span class="sectionnote">Scheduled in demo only. No external publishing occurs.</span>':'<span class="sectionnote">Published sample record.</span>'}</div>`)}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.hasAttribute('data-close'))$('#modal').close();if(t.dataset.go)location.hash=t.dataset.go;if(t.dataset.action==='create')create();if(t.dataset.action==='reviewnext'){const a=articles.find(a=>a.status==='In review');a?review(a.id):toast('No content awaiting review.')}if(t.dataset.review)review(Number(t.dataset.review));if(t.dataset.filter){filter=t.dataset.filter;render()}if(t.dataset.keyword)create(t.dataset.keyword);if(t.dataset.status){const a=articles.find(x=>x.id===Number(t.dataset.id));a.status=t.dataset.status;persist('brand-poc-articles',articles);$('#modal').close();render();toast(`Content moved to ${a.status.toLowerCase()}.`)}if(t.dataset.schedule){modal(`<h2>Schedule demo content</h2><p>Choose a future date for this sample content. No external publishing will occur.</p><form id="scheduleform" data-id="${t.dataset.schedule}"><label>Publish date<input type="date" name="date" required min="${new Date().toISOString().slice(0,10)}"></label><div class="actions"><button class="btn primary">Schedule</button><button type="button" class="btn" data-close>Cancel</button></div></form>`)}if(t.dataset.connect)modal(`<div class="cardhead"><h2>${esc(t.dataset.connect)}</h2><button class="textbtn" data-close>Close ✕</button></div><p>This POC previews the connection workflow. A production integration would use secure authorization, restricted access scopes, and connection health checks.</p><span class="pill blue">No connection has been made</span>`);if(t.dataset.reply)modal(`<div class="cardhead"><h2>Review response preview</h2><button class="textbtn" data-close>Close ✕</button></div><p>Thank you for sharing your experience, ${esc(t.dataset.reply)}. We appreciate your feedback and will use it to improve how we support you. Please contact our team if you’d like to discuss anything further.</p><small>Sample reply · Review before use · No response has been posted</small>`);if(t.dataset.social){const a=articles.find(x=>x.id===Number($('#socialsource').value)),n=t.dataset.social;const copies={LinkedIn:`A practical insight for growing teams: ${a.title}. Start with a clear goal, create useful content, and measure what changes. ${voice.cta}.`,Instagram:`Your next content idea starts here: ${a.title}. Save this for your next planning session. #ContentStrategy #BrandVoice`,Facebook:`What is your biggest content challenge? Our guide to ${a.keyword} is a helpful place to start. Let’s hear your experience.`,X:`Better content starts with a clear plan. Explore ${a.keyword}: know your audience, answer a real question, and measure the result.`};$('#socialpreview').innerHTML=`<h3>${n} preview</h3><p>${esc(copies[n])}</p><small>Template adaptation · Not generated by AI or scheduled</small>`}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='voiceform'){voice=Object.fromEntries(d);const ok=persist('brand-poc-voice',voice);if(ok)toast('Brand voice saved in this browser.')}if(f.id==='createform'){if(!d.get('title').trim()||!d.get('keyword').trim())return toast('Enter a title and keyword.');articles.unshift({id:Date.now(),title:d.get('title').trim(),keyword:d.get('keyword').trim(),intent:d.get('intent'),status:'Draft',score:0,date:'Unscheduled',channel:'Article'});persist('brand-poc-articles',articles);$('#modal').close();filter='All';location.hash='content';render();toast('Sample brief created. Open it to review the outline.')}if(f.id==='prefsform'){if(persist('brand-poc-prefs',{approval:true,notifications:d.has('notifications')}))toast('Preferences saved.')}if(f.id==='scheduleform'){const a=articles.find(x=>x.id===Number(f.dataset.id));a.status='Scheduled';a.date=d.get('date');persist('brand-poc-articles',articles);$('#modal').close();render();toast('Added to the demo schedule.')}});
document.addEventListener('change',e=>{if(e.target.id==='period'){period=e.target.value;render()}});document.addEventListener('input',e=>{if(e.target.id==='keywordsearch')$('#keywordtable').innerHTML=keywordTable(e.target.value)});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();

